leCell className={classes.columnAction} />\n                <TableCell>{t('sharedDevice')}</TableCell>\n                {columns.map((key) => (\n                  <TableCell key={key}>{t(columnsMap.get(key))}</TableCell>\n                ))}\n              </TableRow>\n            </TableHead>\n            <TableBody>\n              {!loading ? (\n                items.flatMap((item) =>\n                  item.events.map((event, index) => (\n                    <TableRow key={event.id}>\n                      <TableCell className={classes.columnAction} padding=\"none\">\n                        {(event.positionId &&\n                          (selected?.event === event ? (\n                            <IconButton size=\"small\" onClick={() => setSelected(null)}>\n                              <GpsFixedIcon fontSize=\"small\" />\n                            </IconButton>\n                          ) : (\n                            <IconButton size=\"small\" onClick={() => setSelected({ item, event })}>\n                              <LocationSearchingIcon fontSize=\"small\" />\n                            </IconButton>\n                          ))) ||\n                          ''}\n                      </TableCell>\n                      <TableCell>{index ? '' : devices[item.deviceId].name}</TableCell>\n                      {columns.map((key) => (\n                        <TableCell key={key}>{formatValue(item, event, key)}</TableCell>\n                      ))}\n                    </TableRow>\n                  )),\n                )\n              ) : (\n                <TableShimmer columns={columns.length + 2} />\n              )}\n            </TableBody>\n          </Table>\n        </div>\n      </div>\n    </PageLayout>\n  );\n};\n\nexport default CombinedReportPage;",
